#requires -Version 5.1
$ErrorActionPreference='Stop'
$module=Import-Module (Join-Path $PSScriptRoot '..\src\WindowsServerMigration.psd1') -Force -PassThru
$script:ToolVersion='0.4.0'
$impl=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\src\AssistiveOsProvided.ps1'))
$names='Get-WsmAssistiveOsProvidedCanonicalTaskSecurity|Get-WsmAssistiveOsProvidedCaptureDefinition|Export-WsmAssistiveOsProvidedTaskCapture|Read-WsmAssistiveOsProvidedCapture|Export-WsmAssistiveOsProvidedBaseline|Get-WsmAssistiveOsProvidedReview|Submit-WsmAssistiveOsProvidedReview|New-WsmAssistiveOsProvidedSealedEvidence|Get-WsmAssistiveOsProvidedIssues'
& $module {param($path,$pattern) . $path;foreach($f in @(Get-Command -CommandType Function | Where-Object {$_.Name -match ('^('+$pattern+')$')})){Set-Item -Path ('Function:\script:'+ $f.Name) -Value $f.ScriptBlock}} $impl $names
$root=Join-Path ([IO.Path]::GetTempPath()) ('wsm-osprovided-'+[Guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory($root)
$passed=0
function Check([bool]$condition,[string]$message){if(-not $condition){throw $message};$script:passed++}
function Reject([scriptblock]$action,[string]$message){$rejected=$false;try{& $action | Out-Null}catch{$rejected=$true};Check $rejected $message}
function CallModule([scriptblock]$block,[object[]]$arguments=@()){& $script:module $block @arguments}
function SaveJson($value,[string]$path){[IO.File]::WriteAllText($path,($value|ConvertTo-Json -Depth 40),(New-Object Text.UTF8Encoding($false)));$path}
function HashFile([string]$path){(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()}
try {
    $task=Get-ScheduledTask -ErrorAction Stop | Select-Object -First 1
    if($null -eq $task){throw 'Native OSProvided acceptance requires at least one actual Task Scheduler task on this Windows host.'}
    $taskName=[string]$task.TaskName;$taskPath=[string]$task.TaskPath
    $identity=CallModule {Get-WsmMachineIdentity}
    $native=Export-ScheduledTask -TaskName $taskName -TaskPath $taskPath -ErrorAction Stop
    $security=CallModule {param($p,$n) Capture-WsmTaskSecurity $p $n} @($taskPath,$taskName)
    $settings=@{TaskName=$taskName;TaskPath=$taskPath;Xml=[string]$native;TaskSecurityCapture=$security;TaskSecurityCaptureStatus='Captured'}
    $hostId=[Guid]::NewGuid().ToString()
    $item=CallModule {param($host,$path,$name,$s) New-WsmItem $host Tasks ScheduledTask ($path+$name) ($path+$name) $s @() Success ScheduledTask} @($hostId,$taskPath,$taskName,$settings)
    $includedItem=CallModule {param($host) New-WsmItem $host System Platform 'fixture baseline' 'fixture-baseline' @{Fixture='include'} @() Success ManualWorkflow} @($hostId)
    $inventory=CallModule {param($source,$rows) New-WsmInventory $source 1 $rows} @([pscustomobject]@{HostId=$hostId;Fingerprint=$identity.Fingerprint;Name=$identity.Name},@($item,$includedItem))
    $inventoryPath=Join-Path $root 'inventory.json';SaveJson $inventory $inventoryPath | Out-Null;$inventoryHash=HashFile $inventoryPath
    $workspace=Join-Path $root 'workspace';CallModule {param($w) Initialize-WsmWorkspace $w | Out-Null} @($workspace)
    $catalog=CallModule {param($w,$p,$h) Import-WsmInventory $w $p $h 'OSProvided fixture'} @($workspace,$inventoryPath,$inventoryHash)
    $catalog=CallModule {param($w,$pair,$rev) Set-WsmGeneralHostMode $w $pair -ExpectedRevision $rev} @($workspace,$catalog.PairId,$catalog.DecisionRevision)
    $sourceCapture=CallModule {param($w,$pair,$rev,$path,$name,$fp) Export-WsmAssistiveOsProvidedTaskCapture -Workspace $w -PairId $pair -DecisionRevision $rev -TaskPath $path -TaskName $name -Role Source -ExpectedHostFingerprint $fp} @($workspace,$catalog.PairId,$catalog.DecisionRevision,$taskPath,$taskName,$identity.Fingerprint)
    $targetCapture=CallModule {param($w,$pair,$rev,$path,$name,$fp) Export-WsmAssistiveOsProvidedTaskCapture -Workspace $w -PairId $pair -DecisionRevision $rev -TaskPath $path -TaskName $name -Role Target -ExpectedHostFingerprint $fp} @($workspace,$catalog.PairId,$catalog.DecisionRevision,$taskPath,$taskName,$identity.Fingerprint)
    Check ($sourceCapture.RawDefinitionReturned -eq $false -and $targetCapture.RawDefinitionReturned -eq $false -and (HashFile $sourceCapture.Path) -ceq $sourceCapture.SHA256) 'Native capture did not save exact protected bytes or leaked raw XML in its result.'

    $sourceProvenance=Join-Path $root 'source-provenance.txt';[IO.File]::WriteAllText($sourceProvenance,'Fixture supplied source OS/provider provenance reference')
    $targetProvenance=Join-Path $root 'target-provenance.txt';[IO.File]::WriteAllText($targetProvenance,'Fixture supplied target OS/provider provenance reference')
    $baseline=CallModule {param($w,$pair,$rev,$sc,$sh,$tc,$th,$sp,$tp) Export-WsmAssistiveOsProvidedBaseline -Workspace $w -PairId $pair -ExpectedDecisionRevision $rev -SourceCapturePath $sc -SourceCaptureHash $sh -TargetCapturePath $tc -TargetCaptureHash $th -SourceProvenancePath $sp -SourceProvenanceHash (Get-FileHash -LiteralPath $sp).Hash -SourceProvenanceOwner 'Source OS evidence custodian' -TargetProvenancePath $tp -TargetProvenanceHash (Get-FileHash -LiteralPath $tp).Hash -TargetProvenanceOwner 'Target OS evidence custodian' -ProviderId 'Fixture provider declaration' -Owner 'Baseline owner' -Ack -AckPristineBaseline} @($workspace,$catalog.PairId,$catalog.DecisionRevision,$sourceCapture.Path,$sourceCapture.SHA256,$targetCapture.Path,$targetCapture.SHA256,$sourceProvenance,$targetProvenance)
    $baselinePath=$baseline.Path;$baselineHash=$baseline.SHA256
    Check ($baseline.Status -eq 'BaselineRecorded' -and -not $baseline.VendorVerified -and -not $baseline.RawDefinitionsReturned) 'Typed baseline producer claimed vendor verification or exposed raw definitions.'
    Reject {CallModule {param($w,$pair,$rev,$sc,$sh,$tc,$th,$sp,$tp) Export-WsmAssistiveOsProvidedBaseline -Workspace $w -PairId $pair -ExpectedDecisionRevision $rev -SourceCapturePath $sc -SourceCaptureHash $sh -TargetCapturePath $tc -TargetCaptureHash $th -SourceProvenancePath $sp -SourceProvenanceHash (Get-FileHash -LiteralPath $sp).Hash -SourceProvenanceOwner 'Source custodian' -TargetProvenancePath $tp -TargetProvenanceHash (Get-FileHash -LiteralPath $tp).Hash -TargetProvenanceOwner 'Target custodian' -ProviderId 'Fixture' -Owner 'Fixture owner' -Ack} @($workspace,$catalog.PairId,$catalog.DecisionRevision,$sourceCapture.Path,$sourceCapture.SHA256,$targetCapture.Path,$targetCapture.SHA256,$sourceProvenance,$targetProvenance)} 'Baseline producer accepted captures without explicit pristine-baseline acknowledgment.'
    $review=CallModule {param($w,$pair,$id,$sc,$sh,$tc,$th,$ip,$ih,$bp,$bh) Get-WsmAssistiveOsProvidedReview -Workspace $w -PairId $pair -ItemId $id -SourceCapturePath $sc -SourceCaptureHash $sh -TargetCapturePath $tc -TargetCaptureHash $th -TargetInventoryPath $ip -TargetInventoryHash $ih -BaselinePath $bp -BaselineHash $bh -BaselineOwner 'Fixture baseline custodian' -AckTrustedBaseline} @($workspace,$catalog.PairId,$item.ItemId,$sourceCapture.Path,$sourceCapture.SHA256,$targetCapture.Path,$targetCapture.SHA256,$inventoryPath,$inventoryHash,$baselinePath,$baselineHash)
    Check ($review.OSProvidedEligible -and -not $review.VendorVerified -and -not $review.ReadinessProof -and $review.ValuesWithheld) 'Exact independent baseline match did not produce a non-readiness, non-vendor-verified review.'
    Reject {CallModule {param($w,$pair,$id,$sc,$sh,$tc,$th,$ip,$ih,$bp,$bh) Get-WsmAssistiveOsProvidedReview -Workspace $w -PairId $pair -ItemId $id -SourceCapturePath $sc -SourceCaptureHash $sh -TargetCapturePath $tc -TargetCaptureHash $th -TargetInventoryPath $ip -TargetInventoryHash $ih -BaselinePath $bp -BaselineHash $bh -BaselineOwner 'Fixture baseline custodian'} @($workspace,$catalog.PairId,$item.ItemId,$sourceCapture.Path,$sourceCapture.SHA256,$targetCapture.Path,$targetCapture.SHA256,$inventoryPath,$inventoryHash,$baselinePath,$baselineHash)} 'Missing trusted-baseline acknowledgment was accepted.'
    Reject {CallModule {param($w,$pair,$id,$sc,$sh,$tc,$th,$ip,$ih,$bp,$bh) Get-WsmAssistiveOsProvidedReview -Workspace $w -PairId $pair -ItemId $id -SourceCapturePath $sc -SourceCaptureHash $sh -TargetCapturePath $tc -TargetCaptureHash $th -TargetInventoryPath $ip -TargetInventoryHash $ih -BaselinePath $bp -BaselineHash $bh -BaselineOwner 'Fixture owner' -AckTrustedBaseline} @($workspace,$catalog.PairId,$item.ItemId,$sourceCapture.Path,('0'*64),$targetCapture.Path,$targetCapture.SHA256,$inventoryPath,$inventoryHash,$baselinePath,$baselineHash)} 'Capture-byte tampering was accepted.'

    $baselineObject=CallModule {param($p,$h) Read-WsmTrustedJson $p $h} @($baselinePath,$baselineHash)
    $customBaseline=ConvertFrom-Json -InputObject ($baselineObject|ConvertTo-Json -Depth 20 -Compress);$customBaseline.Source.TaskXmlSHA256=('c'*64);$customPath=Join-Path $root 'customized-source-baseline.json';SaveJson $customBaseline $customPath | Out-Null;$customHash=HashFile $customPath
    $customReview=CallModule {param($w,$pair,$id,$sc,$sh,$tc,$th,$ip,$ih,$bp,$bh) Get-WsmAssistiveOsProvidedReview -Workspace $w -PairId $pair -ItemId $id -SourceCapturePath $sc -SourceCaptureHash $sh -TargetCapturePath $tc -TargetCaptureHash $th -TargetInventoryPath $ip -TargetInventoryHash $ih -BaselinePath $bp -BaselineHash $bh -BaselineOwner 'Fixture owner' -AckTrustedBaseline} @($workspace,$catalog.PairId,$item.ItemId,$sourceCapture.Path,$sourceCapture.SHA256,$targetCapture.Path,$targetCapture.SHA256,$inventoryPath,$inventoryHash,$customPath,$customHash)
    Check (-not $customReview.OSProvidedEligible -and $customReview.ManualReasons -contains 'SourceDefinitionDoesNotMatchTrustedBaseline') 'Customized same-name source task was classified as OSProvided.'
    $wrongTargetBaseline=ConvertFrom-Json -InputObject ($baselineObject|ConvertTo-Json -Depth 20 -Compress);$wrongTargetBaseline.Target.TaskXmlSHA256=('d'*64);$wrongTargetPath=Join-Path $root 'different-target-baseline.json';SaveJson $wrongTargetBaseline $wrongTargetPath | Out-Null;$wrongTargetHash=HashFile $wrongTargetPath
    $wrongTargetReview=CallModule {param($w,$pair,$id,$sc,$sh,$tc,$th,$ip,$ih,$bp,$bh) Get-WsmAssistiveOsProvidedReview -Workspace $w -PairId $pair -ItemId $id -SourceCapturePath $sc -SourceCaptureHash $sh -TargetCapturePath $tc -TargetCaptureHash $th -TargetInventoryPath $ip -TargetInventoryHash $ih -BaselinePath $bp -BaselineHash $bh -BaselineOwner 'Fixture owner' -AckTrustedBaseline} @($workspace,$catalog.PairId,$item.ItemId,$sourceCapture.Path,$sourceCapture.SHA256,$targetCapture.Path,$targetCapture.SHA256,$inventoryPath,$inventoryHash,$wrongTargetPath,$wrongTargetHash)
    Check (-not $wrongTargetReview.OSProvidedEligible -and $wrongTargetReview.ManualReasons -contains 'TargetDefinitionDoesNotMatchTrustedBaseline') 'Different target definition was accepted as OSProvided.'
    $emptyTarget=CallModule {param($s) New-WsmInventory $s 1 @()} @($inventory.Source);$emptyTargetPath=Join-Path $root 'missing-target-task.json';SaveJson $emptyTarget $emptyTargetPath | Out-Null;$emptyTargetHash=HashFile $emptyTargetPath
    Reject {CallModule {param($w,$pair,$id,$sc,$sh,$tc,$th,$ip,$ih,$bp,$bh) Get-WsmAssistiveOsProvidedReview -Workspace $w -PairId $pair -ItemId $id -SourceCapturePath $sc -SourceCaptureHash $sh -TargetCapturePath $tc -TargetCaptureHash $th -TargetInventoryPath $ip -TargetInventoryHash $ih -BaselinePath $bp -BaselineHash $bh -BaselineOwner 'Fixture owner' -AckTrustedBaseline} @($workspace,$catalog.PairId,$item.ItemId,$sourceCapture.Path,$sourceCapture.SHA256,$targetCapture.Path,$targetCapture.SHA256,$emptyTargetPath,$emptyTargetHash,$baselinePath,$baselineHash)} 'Missing target task was classified as OSProvided.'
    Reject {CallModule {param($w,$pair,$id,$rev,$sc,$sh,$tc,$th,$ip,$ih,$bp,$bh) Submit-WsmAssistiveOsProvidedReview -Workspace $w -PairId $pair -ItemId $id -ExpectedDecisionRevision $rev -SourceCapturePath $sc -SourceCaptureHash $sh -TargetCapturePath $tc -TargetCaptureHash $th -TargetInventoryPath $ip -TargetInventoryHash $ih -BaselinePath $bp -BaselineHash $bh -BaselineOwner 'Fixture owner' -Owner 'Task owner' -Disposition OSProvided -Reason 'Claim built in' -Ack -AckTrustedBaseline} @($workspace,$catalog.PairId,$item.ItemId,$catalog.DecisionRevision,$sourceCapture.Path,$sourceCapture.SHA256,$targetCapture.Path,$targetCapture.SHA256,$inventoryPath,$inventoryHash,$customPath,$customHash)} 'Owner claim/prefix without an exact source baseline match was accepted.'

    $submit=CallModule {param($w,$pair,$id,$rev,$sc,$sh,$tc,$th,$ip,$ih,$bp,$bh) Submit-WsmAssistiveOsProvidedReview -Workspace $w -PairId $pair -ItemId $id -ExpectedDecisionRevision $rev -SourceCapturePath $sc -SourceCaptureHash $sh -TargetCapturePath $tc -TargetCaptureHash $th -TargetInventoryPath $ip -TargetInventoryHash $ih -BaselinePath $bp -BaselineHash $bh -BaselineOwner 'Fixture baseline custodian' -Owner 'Task owner' -Disposition OSProvided -Reason 'Exact task definition and security match the independently supplied baseline.' -Ack -AckTrustedBaseline} @($workspace,$catalog.PairId,$item.ItemId,$catalog.DecisionRevision,$sourceCapture.Path,$sourceCapture.SHA256,$targetCapture.Path,$targetCapture.SHA256,$inventoryPath,$inventoryHash,$baselinePath,$baselineHash)
    $decisionCatalog=CallModule {param($w,$pair,$id,$rev) Set-WsmDecision -Workspace $w -PairId $pair -ItemId @($id) -Decision Include -Reason 'Fixture include for sealed MigrationPlan contract.' -ExpectedRevision $rev -Confirm:$false} @($workspace,$catalog.PairId,$includedItem.ItemId,$submit.DecisionRevision)
    $enabled=CallModule {param($w,$pair,$rev) Enable-WsmAssistiveMode $w $pair -ExpectedRevision $rev} @($workspace,$catalog.PairId,$decisionCatalog.DecisionRevision)
    $after=CallModule {param($w,$pair) Get-WsmCatalog $w $pair} @($workspace,$catalog.PairId)
    $override=@($after.Items|Where-Object ItemId -CEQ $item.ItemId)[0].GeneralHostOverride
    Check ($submit.Status -eq 'OwnerAcceptedOsProvidedBaselineMatch' -and $submit.ReadinessProof -eq $false -and $override.Disposition -eq 'External' -and $override.OsProvidedReview.EvidenceHash -eq $submit.EvidenceHash -and $after.Items[0].ReviewedBy -is [string]) 'Typed OSProvided submit did not preserve the external disposition, exact evidence reference, and compatible ReviewedBy string.'
    $issues=CallModule {param($c,$id) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $c -ItemId $id} @($after,$item.ItemId)
    Check ($issues.Count -eq 0) ('Valid current exact task evidence produced a manual issue: '+($issues|ConvertTo-Json -Depth 20 -Compress))
    $reviewIssues=@(CallModule {param($c) Get-WsmAssistiveReviewIssues $c} @($after))
    Check (@($reviewIssues|Where-Object ItemId -CEQ $item.ItemId).Count -eq 0) ('Selected valid OSProvided exclusion failed the native Assistive review consumer: '+($reviewIssues|ConvertTo-Json -Depth 20 -Compress))
    $invalidSelected=ConvertFrom-Json -InputObject ($after|ConvertTo-Json -Depth 40 -Compress);$invalidSelectedItem=@($invalidSelected.Items|Where-Object ItemId -CEQ $item.ItemId)[0];$invalidSelectedItem.GeneralHostOverride.OsProvidedReview.EvidenceHash=('0'*64)
    $invalidSelectedIssues=@(CallModule {param($c) Get-WsmAssistiveReviewIssues $c} @($invalidSelected))
    Check (@($invalidSelectedIssues|Where-Object ItemId -CEQ $item.ItemId).Count -gt 0) 'Selected excluded item with corrupted OSProvided evidence passed the actual Assistive review consumer.'
    $sealedCatalogItem=@($after.Items|Where-Object {$_.ItemId -ceq $item.ItemId})[0]
    $directSealedSnapshot=CallModule {param($c,$it) New-WsmAssistiveOsProvidedSealedEvidence -Catalog $c -Item $it} @($after,$sealedCatalogItem)
    Check ($directSealedSnapshot.Kind -ceq 'AssistiveOsProvidedSealedEvidence') 'Direct source-at-seal helper did not return the portable snapshot contract.'
    $unrelated=ConvertFrom-Json -InputObject ($after|ConvertTo-Json -Depth 40 -Compress);$unrelated.DecisionRevision++;$other=CallModule {param($host) New-WsmItem $host Tasks ScheduledTask 'Other task' '\Other\Task' @{TaskName='Task';TaskPath='\Other\';Xml='<Task />'} @() Success ScheduledTask} @($hostId);$unrelated.Items=@($unrelated.Items)+@($other)
    $unrelatedIssues=CallModule {param($c,$id) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $c -ItemId $id} @($unrelated,$item.ItemId)
    Check ($unrelatedIssues.Count -eq 0) 'A second unrelated task/catalog decision revision invalidated an unchanged OSProvided task review.'
    $changed=ConvertFrom-Json -InputObject ($after|ConvertTo-Json -Depth 40 -Compress);$changedItem=@($changed.Items|Where-Object ItemId -CEQ $item.ItemId)[0];$changedItem.Settings.Xml=[string]$changedItem.Settings.Xml+' ';$changedItem.SettingsHash=CallModule {param($s) Get-WsmHashText ($s|ConvertTo-Json -Depth 30 -Compress)} @($changedItem.Settings)
    $changedIssues=CallModule {param($c,$id) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $c -ItemId $id} @($changed,$item.ItemId)
    Check (@($changedIssues).Count -eq 1) ('Current task XML change did not invalidate the exact source-definition review: '+($changedIssues|ConvertTo-Json -Depth 10 -Compress))
    $authorityItem=@($after.Items|Where-Object ItemId -CEQ $item.ItemId)[0]
    $sealed=[pscustomobject]@{PairId=$after.PairId;InventoryHash=$after.InventoryHash;DecisionRevision=$after.DecisionRevision;Items=@();Assistive=[pscustomobject]@{DiscoveryAuthority=[pscustomobject]@{OsProvidedItems=@($authorityItem)}}}
    $sealedIssues=CallModule {param($p,$id) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $p -ItemId $id} @($sealed,$item.ItemId)
    Check (@($sealedIssues).Count -eq 0) 'Sealed excluded OSProvided source evidence was not discoverable from DiscoveryAuthority.'
    $sealedInvalid=ConvertFrom-Json -InputObject ($sealed|ConvertTo-Json -Depth 40 -Compress);$sealedInvalid.Assistive.DiscoveryAuthority.OsProvidedItems[0].GeneralHostOverride.OsProvidedReview.EvidenceHash=('0'*64)
    $sealedInvalidIssues=CallModule {param($p,$id) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $p -ItemId $id} @($sealedInvalid,$item.ItemId)
    Check (@($sealedInvalidIssues).Count -eq 1) 'Invalid evidence in sealed excluded OSProvided DiscoveryAuthority was ignored.'
    $planSeed=[pscustomobject]@{SchemaVersion=1;ToolVersion='0.4.0';Kind='MigrationPlan';PairId=$after.PairId;InventoryHash=$after.InventoryHash;InventoryRevision=$after.InventoryRevision;DecisionRevision=$after.DecisionRevision;Items=@([pscustomobject]@{ItemId=$includedItem.ItemId;Decision='Include'})}
    $actualPlan=CallModule {param($p,$c) New-WsmAssistiveMigrationPlanContract $p $c} @($planSeed,$after)
    $actualPlan=CallModule {param($json) ConvertFrom-WsmJson $json} @((ConvertTo-Json -InputObject $actualPlan -Depth 50 -Compress))
    $planContract=CallModule {param($p) Assert-WsmAssistiveContract $p MigrationPlan} @($actualPlan)
    Check ($actualPlan.Kind -ceq 'MigrationPlan' -and $actualPlan.Assistive.DiscoveryAuthority.Dispositions.Count -eq 2 -and $actualPlan.Assistive.DiscoveryAuthority.OsProvidedItems.Count -eq 1 -and $actualPlan.Items.Count -eq 1) 'Actual MigrationPlan producer did not serialize selected Include plus excluded OSProvided authority.'
    $sealedEvidence=$actualPlan.Assistive.DiscoveryAuthority.OsProvidedItems[0].GeneralHostOverride.OsProvidedSealedEvidence
    Check ($sealedEvidence.Kind -ceq 'AssistiveOsProvidedSealedEvidence' -and $sealedEvidence.SourceAtSeal.EvidenceVerified -and $sealedEvidence.SourceAtSeal.ProvenanceVerified -and $sealedEvidence.Baseline.Source.ProvenanceReference -like 'Verified at source sealing*' -and $sealedEvidence.Receipt.TrustedBaselinePath -like 'Verified at source sealing*') 'MigrationPlan producer did not carry portable source-verified baseline and provenance snapshots.'
    $planContract=CallModule {param($p) Assert-WsmAssistiveContract $p MigrationPlan} @($actualPlan)
    $oldPlan=CallModule {param($json) ConvertFrom-WsmJson $json} @((ConvertTo-Json -InputObject $actualPlan -Depth 60 -Compress))
    $oldProof=$oldPlan.Assistive.DiscoveryAuthority.OsProvidedItems[0];$oldProof.GeneralHostOverride.OsProvidedReview.EvidencePath='X:\sealed-source-workspace-unavailable\receipt.json'
    Check (-not [IO.File]::Exists($oldProof.GeneralHostOverride.OsProvidedReview.EvidencePath) -and $oldProof.GeneralHostOverride.OsProvidedSealedEvidence.Baseline.Source.ProvenanceReference -like 'Verified at source sealing*') 'Relocated sealed plan fixture still depends on original source-workspace evidence paths.'
    $oldSnapshot=$oldProof.GeneralHostOverride.OsProvidedSealedEvidence;$oldSnapshot.Receipt.NativeTargetReadbackUtc=[DateTime]::UtcNow.AddDays(-3).ToString('o');$oldSnapshot.PSObject.Properties.Remove('SnapshotHash');$oldSnapshot|Add-Member NoteProperty SnapshotHash (CallModule {param($v) Get-WsmHashText ($v|ConvertTo-Json -Depth 80 -Compress)} @($oldSnapshot))
    $oldStaticIssues=CallModule {param($p,$id) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $p -ItemId $id} @($oldPlan,$item.ItemId)
    Check (@($oldStaticIssues).Count -eq 0) ('Immutable sealed OSProvided evidence expired solely because its native review receipt was older than 24 hours: '+($oldStaticIssues|ConvertTo-Json -Depth 20 -Compress))
    $oldNativeIssues=CallModule {param($p,$id,$fp) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $p -ItemId $id -TargetFingerprint $fp -VerifyNativeTarget} @($oldPlan,$item.ItemId,$identity.Fingerprint)
    Check (@($oldNativeIssues).Count -eq 0) ('Fresh native target verification failed for an unchanged sealed task: '+($oldNativeIssues|ConvertTo-Json -Depth 10 -Compress))
    $otherTask=Get-ScheduledTask -ErrorAction Stop | Where-Object { $_.TaskPath -cne $taskPath -or $_.TaskName -cne $taskName } | Select-Object -First 1
    if($null -eq $otherTask){throw 'Native target drift fixture requires a second actual Task Scheduler task.'}
    $otherXml=Export-ScheduledTask -TaskPath ([string]$otherTask.TaskPath) -TaskName ([string]$otherTask.TaskName) -ErrorAction Stop
    $otherSecurity=CallModule {param($p,$n) Capture-WsmTaskSecurity $p $n} @([string]$otherTask.TaskPath,[string]$otherTask.TaskName)
    $driftSnapshot=$oldPlan.Assistive.DiscoveryAuthority.OsProvidedItems[0].GeneralHostOverride.OsProvidedSealedEvidence;$driftBaseline=ConvertFrom-Json -InputObject ($driftSnapshot.Baseline|ConvertTo-Json -Depth 40 -Compress);$driftReceipt=ConvertFrom-Json -InputObject ($driftSnapshot.Receipt|ConvertTo-Json -Depth 40 -Compress)
    $otherXmlHash=CallModule {param($v) Get-WsmHashText ([string]$v)} @([string]$otherXml);$otherSecurityHash=CallModule {param($s) Get-WsmHashText ((Get-WsmAssistiveOsProvidedCanonicalTaskSecurity $s)|ConvertTo-Json -Depth 30 -Compress)} @($otherSecurity)
    $driftReceipt.TargetTaskXmlSHA256=$otherXmlHash;$driftReceipt.TargetTaskSecuritySHA256=$otherSecurityHash;$driftReceipt.TargetBaselineMatched=$true;$driftReceipt.DefinitionsDiffer=([string]$driftReceipt.SourceTaskXmlSHA256 -ine $otherXmlHash -or [string]$driftReceipt.SourceTaskSecuritySHA256 -ine $otherSecurityHash)
    $driftBaseline.Target.TaskXmlSHA256=$otherXmlHash;$driftBaseline.Target.TaskSecuritySHA256=$otherSecurityHash;$driftSnapshot.Receipt=$driftReceipt;$driftSnapshot.Baseline=$driftBaseline;$driftSnapshot.PSObject.Properties.Remove('SnapshotHash');$driftSnapshot|Add-Member NoteProperty SnapshotHash (CallModule {param($v) Get-WsmHashText ($v|ConvertTo-Json -Depth 80 -Compress)} @($driftSnapshot))
    $driftPlan=CallModule {param($json) ConvertFrom-WsmJson $json} @((ConvertTo-Json -InputObject $oldPlan -Depth 60 -Compress));$driftItem=$driftPlan.Assistive.DiscoveryAuthority.OsProvidedItems[0]
    $nativeDriftIssues=CallModule {param($p,$id,$fp) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $p -ItemId $id -TargetFingerprint $fp -VerifyNativeTarget} @($driftPlan,$item.ItemId,$identity.Fingerprint)
    Check (@($nativeDriftIssues).Count -eq 1 -and [string]$nativeDriftIssues[0].Issue -match 'Native target task XML or security differs') 'Fresh native verification accepted task XML/security drift on the sealed target.'
    $unselectedPlan=CallModule {param($json) ConvertFrom-WsmJson $json} @((ConvertTo-Json -InputObject $oldPlan -Depth 60 -Compress));$unselectedPlan.Assistive.DiscoveryAuthority.Dispositions|Where-Object ItemId -CEQ $item.ItemId|ForEach-Object {$_.Selected=$false};$unselectedPlan.Assistive.DiscoveryAuthority.OsProvidedItems[0].GeneralHostOverride.OsProvidedSealedEvidence.SnapshotHash=('0'*64)
    $unselectedIssues=CallModule {param($p) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $p} @($unselectedPlan)
    Check (@($unselectedIssues).Count -eq 0) 'Bulk sealed evidence scan blocked on an unselected item.'
    $unselectedExplicit=CallModule {param($p,$id) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $p -ItemId $id} @($unselectedPlan,$item.ItemId)
    Check (@($unselectedExplicit).Count -eq 1) 'Explicit item-scoped evidence reporting failed to surface invalid proof for an unselected item.'
    $evidenceBytes=[IO.File]::ReadAllBytes($submit.EvidencePath);$tamperedBytes=[byte[]]$evidenceBytes.Clone();$tamperedBytes[10]=[byte]($tamperedBytes[10] -bxor 1);[IO.File]::WriteAllBytes($submit.EvidencePath,$tamperedBytes)
    $tamperedIssues=CallModule {param($c,$id) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $c -ItemId $id} @($after,$item.ItemId)
    $tamperedSummary=$tamperedIssues|ConvertTo-Json -Depth 10 -Compress
    Check ($tamperedSummary -match 'Trusted SHA256 mismatch') ('Tampered evidence file remained a valid OSProvided disposition: '+$tamperedSummary)
    [IO.File]::WriteAllBytes($submit.EvidencePath,$evidenceBytes)
    $futureEvidence=CallModule {param($p,$h) Read-WsmTrustedJson $p $h} @($submit.EvidencePath,$submit.EvidenceHash);$futureEvidence.NativeTargetReadbackUtc=[DateTime]::UtcNow.AddHours(1).ToString('o');$futurePath=Join-Path $root 'future-readback.json';SaveJson $futureEvidence $futurePath | Out-Null
    $futureCatalog=ConvertFrom-Json -InputObject ($after|ConvertTo-Json -Depth 40 -Compress);$futureItem=@($futureCatalog.Items|Where-Object ItemId -CEQ $item.ItemId)[0];$futureItem.GeneralHostOverride.OsProvidedReview.EvidencePath=$futurePath;$futureItem.GeneralHostOverride.OsProvidedReview.EvidenceHash=HashFile $futurePath
    $futureIssues=CallModule {param($c,$id) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $c -ItemId $id} @($futureCatalog,$item.ItemId)
    Check (@($futureIssues).Count -eq 1) 'Future-dated native target readback was accepted.'
    Reject {CallModule {param($w,$pair,$id,$rev,$sc,$sh,$tc,$th,$ip,$ih,$bp,$bh) Submit-WsmAssistiveOsProvidedReview -Workspace $w -PairId $pair -ItemId $id -ExpectedDecisionRevision $rev -SourceCapturePath $sc -SourceCaptureHash $sh -TargetCapturePath $tc -TargetCaptureHash $th -TargetInventoryPath $ip -TargetInventoryHash $ih -BaselinePath $bp -BaselineHash $bh -BaselineOwner 'Fixture' -Owner 'Fixture' -Disposition Manual -Reason 'manual' -Ack -AckTrustedBaseline} @($workspace,$catalog.PairId,$item.ItemId,$catalog.DecisionRevision,$sourceCapture.Path,$sourceCapture.SHA256,$targetCapture.Path,$targetCapture.SHA256,$inventoryPath,$inventoryHash,$baselinePath,$baselineHash)} 'Stale catalog revision was accepted after OSProvided apply.'
    $current=CallModule {param($w,$pair) Get-WsmCatalog $w $pair} @($workspace,$catalog.PairId)
    $manualSubmit=CallModule {param($w,$pair,$id,$rev,$sc,$sh,$tc,$th,$ip,$ih,$bp,$bh) Submit-WsmAssistiveOsProvidedReview -Workspace $w -PairId $pair -ItemId $id -ExpectedDecisionRevision $rev -SourceCapturePath $sc -SourceCaptureHash $sh -TargetCapturePath $tc -TargetCaptureHash $th -TargetInventoryPath $ip -TargetInventoryHash $ih -BaselinePath $bp -BaselineHash $bh -BaselineOwner 'Fixture owner' -Owner 'Task owner' -Disposition Manual -Reason 'Customized source definition does not match the supplied pristine baseline; retain for manual migration.' -Ack -AckTrustedBaseline} @($workspace,$catalog.PairId,$item.ItemId,$current.DecisionRevision,$sourceCapture.Path,$sourceCapture.SHA256,$targetCapture.Path,$targetCapture.SHA256,$inventoryPath,$inventoryHash,$customPath,$customHash)
    $manualCatalog=CallModule {param($w,$pair) Get-WsmCatalog $w $pair} @($workspace,$catalog.PairId)
    $manualIssues=CallModule {param($c,$id) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $c -ItemId $id} @($manualCatalog,$item.ItemId)
    Check ($manualSubmit.Status -eq 'ManualRequired' -and @($manualIssues).Count -eq 0) ('Valid owner-reviewed manual state was rejected because its definitions differ from the OSProvided baseline: '+($manualIssues|ConvertTo-Json -Depth 10 -Compress))
    $unknownManual=ConvertFrom-Json -InputObject ($manualCatalog|ConvertTo-Json -Depth 40 -Compress);$unknownManual.Items[0].GeneralHostOverride.OsProvidedReview.Status='Unknown'
    $unknownManualIssues=CallModule {param($c,$id) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $c -ItemId $id} @($unknownManual,$item.ItemId)
    Check (@($unknownManualIssues).Count -eq 1) 'Manual evidence with an unknown status was accepted.'
    $ownerMismatch=ConvertFrom-Json -InputObject ($manualCatalog|ConvertTo-Json -Depth 40 -Compress);$ownerMismatch.Items[0].GeneralHostOverride.Owner='Different owner'
    $ownerMismatchIssues=CallModule {param($c,$id) Get-WsmAssistiveOsProvidedIssues -CatalogOrPlan $c -ItemId $id} @($ownerMismatch,$item.ItemId)
    Check (@($ownerMismatchIssues).Count -eq 1) 'Manual evidence whose owner differs from the current override was accepted.'
} finally { if([IO.Directory]::Exists($root)){Remove-Item -LiteralPath $root -Recurse -Force};Remove-Module $module -Force }
Write-Output ("Test-AssistiveOsProvided.ps1 passed {0} checks." -f $passed)
